    ["HOUSING_CREATENEIGHBORHOOD_CHARTER_OPENDESCRIPTION"] = { en = "|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t every player on the charter will be a neighborhood manager |n|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t for the first 24 hours, only charter players may purchase a plot |n|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t after 24 hours, any player may purchase a plot |n|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t can't be converted into a private neighborhood", it = "|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t ogni giocatore presente nell'atto sarà responsabile del vicinato |n|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t per le prime 24 ore, solo i giocatori presenti nell'atto possono acquistare un lotto |n|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t dopo 24 ore, qualsiasi giocatore può acquistare un lotto |n|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t non può essere convertito in un vicinato privato" },
    ["HOUSING_CREATENEIGHBORHOOD_CHARTER_PRIVATEDESCRIPTION"] = { en = "|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t every player on the charter will be a neighborhood manager |n|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t neighborhood managers can add other players to the neighborhood |n|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t can be converted into an open neighborhood", it = "|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t ogni giocatore presente nell'atto sarà responsabile del vicinato |n|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t i responsabili del vicinato possono aggiungere altri giocatori al vicinato |n|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t può essere convertito in un vicinato aperto" },
    ["HOUSING_CREATENEIGHBORHOOD_GUILD_OPENDESCRIPTION"] = { en = "|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t for the first 24 hours, only guild members may purchase a plot |n|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t after 24 hours, any player may purchase a plot |n|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t new subdivisions will not be created when the neighborhood is full |n|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t can't be converted into a private neighborhood", it = "|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t per le prime 24 ore, solo i membri della gilda possono acquistare un lotto |n|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t dopo 24 ore, qualsiasi giocatore può acquistare un lotto |n|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t non verranno create nuove suddivisioni quando il vicinato è al completo |n|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t non può essere convertito in un vicinato privato" },
    ["HOUSING_CREATENEIGHBORHOOD_GUILD_PRIVATEDESCRIPTION"] = { en = "|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t only players who are a part of your guild may purchase a plot |n|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t players not in the guild will be kicked from the neighborhood |n|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t new subdivisions will be created when the neighborhood is full |n|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t can be converted into an open neighborhood if there are no subdivisions", it = "|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t solo i giocatori che fanno parte della tua gilda possono acquistare un lotto |n|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t i giocatori che non fanno parte della gilda verranno espulsi dal vicinato |n|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t verranno create nuove suddivisioni quando il vicinato è al completo |n|TInterface/QuestFrame/UI-Quest-BulletPoint.blp:0|t può essere convertito in un vicinato aperto se non ci sono suddivisioni" },
